input.command:
cd /tmp; run(){ rm -rf /tmp/g; mkdir -p /tmp/g/data /tmp/g/logs; [ -f "$1/data/recovered.json" ] && cp "$1/data/recovered.json" /tmp/g/data/; cp /data/database.db /tmp/g/data/;
bwrap --bind / / --bind /tmp/g/data /data --bind /tmp/g/logs /logs --ro-bind /verifier_out/tests /tests bash /tests/test.sh >/tmp/g/out 2>&1; echo "$1 -> $(cat /tmp/g/logs/verifier/reward.txt) $(tail -1 /tmp/g/out)"; }
for c in /candidates/A /candidates/B /candidates/C /nonexistent_empty /verifier_out/near_misses/*; do run $c; done

